function icon(name, size) {
  const d = ICONS[name];
  if (!d) return '';
  const s = size || 18;
  return `<svg class="ico" width="${s}" height="${s}" viewBox="${d[0]}" aria-hidden="true" focusable="false" fill="currentColor">${d[1]}</svg>`;
}
